// Verifies that this event really came from LendLoop's Convex backend.
// Signed string: "<timestamp>.loan-event.<raw body>", HMAC-SHA256, header "v1=<hex>".
// Refuses missing/old timestamps (5-minute window) and compares in constant time.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;

const secret = $env.CONVEX_TO_N8N_SECRET;
if (!secret || secret.length < 32) throw new Error('CONVEX_TO_N8N_SECRET is not set in the n8n environment');

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');

// The Webhook node keeps the exact bytes Convex signed ("Raw Body" option).
const raw = item.binary && item.binary.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : JSON.stringify(item.json.body);

const reject = (reason) => [{ json: { valid: false, reason } }];
if (!/^\d{1,12}$/.test(timestamp) || !signature.startsWith('v1=')) return reject('missing or malformed signature');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('timestamp outside the 5-minute window');

const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.loan-event.${raw}`).digest();
const given = Buffer.from(signature.slice(3), 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return reject('signature mismatch');

let event;
try { event = JSON.parse(raw); } catch (e) { return reject('body is not JSON'); }
if (!event.eventId || !event.recipient || !event.recipient.email) return reject('event is missing fields');

// Delivery is at-least-once: Convex retries if our answer got lost. Remember recent
// event ids so a retry never sends the same email twice.
const memory = $getWorkflowStaticData('global');
memory.seen = Array.isArray(memory.seen) ? memory.seen : [];
const duplicate = memory.seen.includes(event.eventId);
if (!duplicate) {
  memory.seen.push(event.eventId);
  if (memory.seen.length > 1000) memory.seen = memory.seen.slice(-1000);
}
return [{ json: { valid: true, duplicate, event } }];

// Turns one LendLoop event into one short, plain-text email. Uses only the
// fields Convex sent: first names, the tool's name, the dates.
const app = ($env.APP_URL || 'http://localhost:3000').replace(/\/$/, '');
const day = (d) => new Date(`${d}T00:00:00Z`).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const REASONS = {
  dates_taken: 'those dates went to another neighbour',
  listing_deleted: 'the owner took the listing down',
  listing_removed: 'the listing was removed by an admin',
};

return $input.all().map(({ json }) => {
  const e = json.event;
  const tool = e.tool.name;
  const other = e.otherParty.firstName;
  const range = `${day(e.dates.start)} – ${day(e.dates.end)}`;
  const copy = {
    'loan.requested': [
      `${other} would like to borrow your ${tool}`,
      `${other} has asked to borrow your ${tool} for ${range}.\n\nApprove or decline it here:\n${app}/requests`,
    ],
    'loan.approved': [
      `You can borrow the ${tool}`,
      `${other} approved your request for the ${tool} (${range}).\n\nPlease return it by ${day(e.dates.end)}.\n${app}/requests?tab=mine`,
    ],
    'loan.declined': [
      `Your request for the ${tool} was declined`,
      (e.reason
        ? `Your request for the ${tool} (${range}) was declined automatically: ${REASONS[e.reason] || 'it could not go ahead'}.`
        : `${other} can't lend the ${tool} for ${range} this time.`) +
        `\n\nSee what else is available:\n${app}/tools`,
    ],
    'loan.cancelled': [
      `${other} cancelled their request`,
      `${other} no longer needs your ${tool} for ${range}. There is nothing you need to do.`,
    ],
    'loan.returned': [
      `The ${tool} is marked as returned`,
      `${other} marked the ${tool} as returned. Thank you for being a good neighbour.`,
    ],
  }[e.type] || [`An update about the ${tool}`, `There is an update on your loan:\n${app}/requests`];

  return {
    json: {
      eventId: e.eventId,
      to: e.recipient.email,
      subject: copy[0],
      text: `Hi ${e.recipient.firstName},\n\n${copy[1]}\n\n— LendLoop`,
    },
  };
});

// Signs a request to Convex: HMAC-SHA256 over "<timestamp>.<purpose>.<body>".
// The secret comes from the n8n environment (docker-compose / .env), never from this workflow.
const crypto = require('crypto');
function signFor(purpose, body) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret || secret.length < 32) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n environment');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${purpose}.${body}`).digest('hex');
  return { timestamp, signature, body };
}

function errorText(json) {
  const e = json.error;
  if (!e) return json.message || 'Unknown error';
  return typeof e === 'string' ? e : (e.description || e.message || JSON.stringify(e)).slice(0, 500);
}

// Writes the outcome back to Convex. Convex treats a repeat of the same key as
// a no-op, so this node's retries can never create a second record.
return $input.all().map((item, i) => {
  const source = $('Compose email').itemMatching(i).json;
  const payload = { eventId: source.eventId, status: 'sent', executionId: String($execution.id) };
  return { json: signFor('notification-result', JSON.stringify(payload)) };
});

